// Placeholder product images (docs/specs/006-product-images), generated by
// scripts/generate-placeholders.tsx into public/images/placeholders/. One per
// builder category, named by category slug, plus the extra views below.
export const PLACEHOLDER_DIR = "/images/placeholders"

export function placeholderUrl(name: string): string {
  return `${PLACEHOLDER_DIR}/${name}.svg`
}

// Extra views for products with several images, with the text the seed
// appends to the product name for their alt text
export const PLACEHOLDER_VIEWS = {
  box: "in the box",
  detail: "detail view",
} as const
